def local_evidence(xml):
    paragraphs=paras(xml)
    first=next(i for i,p in enumerate(paragraphs) if p.startswith('10°'))
    last=next(i for i,p in enumerate(paragraphs) if p.startswith("Le régime local est applicable aux titulaires d'un avantage vieillesse"))
    return '\n'.join(no_tags(p) for p in paragraphs[first:last+1])
